import json
palette=[1,3,5,7,9]
grid=[]
for r in range(28):
    row=[]
    for c in range(28):
        if r < 2:
            value=1
        elif r == 2:
            value=1 if c < 2 else 4
        elif c < 2:
            value=1
        elif c == 2:
            value=4
        else:
            value=palette[(r+c)%5]
        row.append(value)
    grid.append(row)
# Preserve the irregular initial seed values from the input pattern.
for r,c,value in [(3,4,2),(3,5,1),(4,3,2),(5,3,1)]:
    grid[r][c]=value
assert len(grid)==28 and all(len(row)==28 for row in grid)
assert all(0 <= cell <= 9 for row in grid for cell in row)
print(json.dumps({'action':'submit','grid':grid},separators=(',',':')))

